      <path d="M23.5 6.2a3.02 3.02 0 0 0-2.12-2.14C19.5 3.55 12 3.55 12 3.55s-7.5 0-9.38.51A3.02 3.02 0 0 0 .5 6.2C0 8.08 0 12 0 12s0 3.92.5 5.8a3.02 3.02 0 0 0 2.12 2.14c1.88.51 9.38.51 9.38.51s7.5 0 9.38-.51a3.02 3.02 0 0 0 2.12-2.14C24 15.92 24 12 24 12s0-3.92-.5-5.8ZM9.6 15.6V8.4l6.27 3.6-6.27 3.6Z"/>
    </svg>,
];
/** Links to other sites open in a new tab. */
const newTab = (href: string) => (/^https?:/.test(href) ? { target: "_blank", rel: "noreferrer noopener" } : {});
export default function FooterSectionsMega({ content }: { content?: Partial<ArtemisFooterContent> } = {}) {
    const copy = { ...DEFAULT, ...content };
    const social: ArtemisFooterSocialLink[] = copy.social;
const artemisInstanceId = useArtemisInstanceId();


    const reduce = useReducedMotion();
    const [email, setEmail] = useState("");
    const [focused, setFocused] = useState(false);
    const [state, setState] = useState<ButtonState>("idle");
    const timers = useRef<number[]>([]);
    useEffect(() => {
        const pending = timers;
        return () => pending.current.forEach((t) => window.clearTimeout(t));
    }, []);
    function onSubmit(event: FormEvent<HTMLFormElement>) {
        event.preventDefault();
        if (state === "loading")
            return;
        timers.current.forEach((t) => window.clearTimeout(t));
        timers.current = [];
        setState("loading");
        timers.current.push(window.setTimeout(() => {
            setState("success");
            setEmail("");
            timers.current.push(window.setTimeout(() => setState("idle"), SUCCESS_MS));
        }, LOADING_MS));
    }
