                </p>
                <span className="art:mt-5 art:inline-flex art:w-fit art:items-center art:gap-2 art:rounded-full art:border art:border-border art:bg-background art:px-3 art:py-1.5 art:text-muted-foreground art:text-xs">
                  <span className="art:relative art:flex art:size-2">
                    <span className="art:absolute art:inline-flex art:size-full art:animate-ping art:rounded-full art:bg-emerald-500/70"/>
                    <span className="art:relative art:inline-flex art:size-2 art:rounded-full art:bg-emerald-500"/>
                  </span>
                  {copy.status}
                </span>
                <div className="art:mt-8">
                  <p className="art:font-medium art:text-foreground art:text-sm">
                    {copy.newsletter.title}
                  </p>
                  <p className="art:mt-1 art:text-muted-foreground art:text-sm">
                    {copy.newsletter.text}
                  </p>
                  <form className="art:mt-4 art:flex art:flex-col art:gap-2.5 art:@min-[640px]/artemis:flex-row" onSubmit={onSubmit}>
                    <label htmlFor={`${artemisInstanceId}-R_9bsnpfdb_`} className="art:sr-only">
                      {"Email address"}
                    </label>
                    <div className="art:flex art:flex-col art:gap-1.5 art:w-full art:flex-1">
                      <div data-state={focused ? "focused" : "idle"} className={`art:relative art:h-10 art:overflow-hidden art:rounded-full art:border art:bg-background art:transition-colors art:duration-200 ${focused ? "art:border-foreground/60" : "art:border-border"}`}>
                        <input id={`${artemisInstanceId}-R_9bsnpfdb_`} type="email" required placeholder={copy.newsletter.placeholder} className="art:peer art:h-full art:w-full art:bg-transparent art:caret-foreground art:outline-none art:px-5 art:text-foreground art:text-sm art:placeholder:text-muted-foreground" value={email} onChange={(e) => setEmail(e.target.value)} onFocus={() => setFocused(true)} onBlur={() => setFocused(false)}/>
                      </div>
                      <div className="art:contents"/>
                    </div>
                    <StatefulButton type="submit" state={state} loadingText={copy.newsletter.sending} successText={copy.newsletter.sent} className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:bg-primary art:text-primary-foreground art:hover:bg-primary/90 art:gap-2 art:px-6 art:text-base art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:shrink-0 art:h-9 art:rounded-full" tabIndex={0}>
                      {copy.newsletter.button}
