              <motion.div className="art:grid art:grid-cols-2 art:gap-8 art:@min-[640px]/artemis:grid-cols-3" initial={HIDDEN} whileInView={SHOWN} viewport={VIEWPORT} transition={reduce ? INSTANT : reveal(SECOND_DELAY)}>
                {copy.columns.map((column, index) => <div key={index} className="art:flex art:flex-col">
                  <p className="art:font-medium art:text-foreground art:text-sm">
                    {column.title}
                  </p>
                  <ul className="art:mt-4 art:flex art:flex-col art:gap-3">
                    {column.links.map((link, linkIndex) => <li key={linkIndex}>
                      <a href={link.href} {...newTab(link.href)} className="art:inline-flex art:w-fit art:items-center art:text-foreground art:text-sm art:opacity-60 art:outline-none art:transition-opacity art:hover:opacity-100 art:focus-visible:underline art:focus-visible:underline-offset-4 art:focus-visible:opacity-100">
